CREATE TABLE "AlertRules" (
    "Id" bigint GENERATED BY DEFAULT AS IDENTITY,
    "UserId" text NOT NULL,
    "Symbol" text NOT NULL,
    "RuleType" text NOT NULL,
    "Threshold" double precision NOT NULL,
    "Enabled" boolean NOT NULL,
    "CreatedAt" timestamp without time zone NOT NULL,
    "LastTriggeredAt" timestamp without time zone,
    "LastTriggeredPrice" double precision,
    CONSTRAINT "PK_AlertRules" PRIMARY KEY ("Id")
);


CREATE TABLE "AspNetRoles" (
    "Id" text NOT NULL,
    "Name" character varying(256),
    "NormalizedName" character varying(256),
    "ConcurrencyStamp" text,
    CONSTRAINT "PK_AspNetRoles" PRIMARY KEY ("Id")
);


CREATE TABLE "AspNetUsers" (
    "Id" text NOT NULL,
    "CreatedAt" timestamp without time zone NOT NULL,
    "UserName" character varying(256),
    "NormalizedUserName" character varying(256),
    "Email" character varying(256),
    "NormalizedEmail" character varying(256),
    "EmailConfirmed" boolean NOT NULL,
    "PasswordHash" text,
    "SecurityStamp" text,
    "ConcurrencyStamp" text,
    "PhoneNumber" text,
    "PhoneNumberConfirmed" boolean NOT NULL,
    "TwoFactorEnabled" boolean NOT NULL,
    "LockoutEnd" timestamp with time zone,
    "LockoutEnabled" boolean NOT NULL,
    "AccessFailedCount" integer NOT NULL,
    CONSTRAINT "PK_AspNetUsers" PRIMARY KEY ("Id")
);


CREATE TABLE "FundNavs" (
    "Id" bigint GENERATED BY DEFAULT AS IDENTITY,
    "FundCode" text NOT NULL,
    "Date" timestamp without time zone NOT NULL,
    "Nav" double precision NOT NULL,
    "AccNav" double precision NOT NULL,
    "ChangePct" double precision NOT NULL,
    CONSTRAINT "PK_FundNavs" PRIMARY KEY ("Id")
);


CREATE TABLE "IndexDailies" (
    "Id" bigint GENERATED BY DEFAULT AS IDENTITY,
    "Code" text NOT NULL,
    "Market" integer NOT NULL,
    "Date" timestamp without time zone NOT NULL,
    "Open" double precision NOT NULL,
    "High" double precision NOT NULL,
    "Low" double precision NOT NULL,
    "Close" double precision NOT NULL,
    "Volume" double precision NOT NULL,
    "Amount" double precision NOT NULL,
    "ChangePct" double precision NOT NULL,
    CONSTRAINT "PK_IndexDailies" PRIMARY KEY ("Id")
);


CREATE TABLE "LprRates" (
    "Id" bigint GENERATED BY DEFAULT AS IDENTITY,
    "Date" timestamp without time zone NOT NULL,
    "Lpr1Y" double precision NOT NULL,
    "Lpr5Y" double precision NOT NULL,
    CONSTRAINT "PK_LprRates" PRIMARY KEY ("Id")
);


CREATE TABLE "MoneyFlowDailies" (
    "Id" bigint GENERATED BY DEFAULT AS IDENTITY,
    "Symbol" text NOT NULL,
    "Date" timestamp without time zone NOT NULL,
    "MainNet" double precision NOT NULL,
    "LargeNet" double precision NOT NULL,
    "MidNet" double precision NOT NULL,
    "SmallNet" double precision NOT NULL,
    CONSTRAINT "PK_MoneyFlowDailies" PRIMARY KEY ("Id")
);


CREATE TABLE "MoneySupplies" (
    "Id" bigint GENERATED BY DEFAULT AS IDENTITY,
    "Month" timestamp without time zone NOT NULL,
    "M2" double precision NOT NULL,
    "M1" double precision NOT NULL,
    "M0" double precision NOT NULL,
    "M2YoY" double precision NOT NULL,
    "M1YoY" double precision NOT NULL,
    "M0YoY" double precision NOT NULL,
    CONSTRAINT "PK_MoneySupplies" PRIMARY KEY ("Id")
);


CREATE TABLE "ReserveRatios" (
    "Id" bigint GENERATED BY DEFAULT AS IDENTITY,
    "Date" timestamp without time zone NOT NULL,
    "Large" double precision NOT NULL,
    "Small" double precision NOT NULL,
    CONSTRAINT "PK_ReserveRatios" PRIMARY KEY ("Id")
);


CREATE TABLE "ShiborRates" (
    "Id" bigint GENERATED BY DEFAULT AS IDENTITY,
    "Period" text NOT NULL,
    "Date" timestamp without time zone NOT NULL,
    "Rate" double precision NOT NULL,
    "ChangeBp" double precision NOT NULL,
    CONSTRAINT "PK_ShiborRates" PRIMARY KEY ("Id")
);


CREATE TABLE "StockBasics" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "Symbol" character varying(12) NOT NULL,
    "Name" character varying(40) NOT NULL,
    "SecMarket" integer NOT NULL,
    "Type" text NOT NULL,
    "UpdatedAt" timestamp without time zone NOT NULL,
    CONSTRAINT "PK_StockBasics" PRIMARY KEY ("Id")
);


CREATE TABLE "StockDailies" (
    "Id" bigint GENERATED BY DEFAULT AS IDENTITY,
    "Symbol" text NOT NULL,
    "Date" timestamp without time zone NOT NULL,
    "Open" double precision NOT NULL,
    "High" double precision NOT NULL,
    "Low" double precision NOT NULL,
    "Close" double precision NOT NULL,
    "Volume" double precision NOT NULL,
    "Amount" double precision NOT NULL,
    "ChangePct" double precision NOT NULL,
    CONSTRAINT "PK_StockDailies" PRIMARY KEY ("Id")
);


CREATE TABLE "StockFundamentals" (
    "Id" bigint GENERATED BY DEFAULT AS IDENTITY,
    "Symbol" text NOT NULL,
    "Name" text NOT NULL,
    "Industry" text,
    "ClosePrice" double precision NOT NULL,
    "ChangePct" double precision,
    "PeTtm" double precision,
    "PbMrq" double precision,
    "PsTtm" double precision,
    "MarketCap" double precision,
    "ReportDate" timestamp without time zone,
    "Revenue" double precision NOT NULL,
    "RevenueYoY" double precision,
    "NetProfit" double precision NOT NULL,
    "NetProfitYoY" double precision,
    "Roe" double precision,
    "GrossMargin" double precision,
    "NetMargin" double precision,
    "UpdatedAt" timestamp without time zone NOT NULL,
    CONSTRAINT "PK_StockFundamentals" PRIMARY KEY ("Id")
);


CREATE TABLE "StockMinutes" (
    "Id" bigint GENERATED BY DEFAULT AS IDENTITY,
    "Symbol" text NOT NULL,
    "Time" timestamp without time zone NOT NULL,
    "Open" double precision NOT NULL,
    "High" double precision NOT NULL,
    "Low" double precision NOT NULL,
    "Close" double precision NOT NULL,
    "Volume" double precision NOT NULL,
    CONSTRAINT "PK_StockMinutes" PRIMARY KEY ("Id")
);


CREATE TABLE "AspNetRoleClaims" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "RoleId" text NOT NULL,
    "ClaimType" text,
    "ClaimValue" text,
    CONSTRAINT "PK_AspNetRoleClaims" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_AspNetRoleClaims_AspNetRoles_RoleId" FOREIGN KEY ("RoleId") REFERENCES "AspNetRoles" ("Id") ON DELETE CASCADE
);


CREATE TABLE "AspNetUserClaims" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "UserId" text NOT NULL,
    "ClaimType" text,
    "ClaimValue" text,
    CONSTRAINT "PK_AspNetUserClaims" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_AspNetUserClaims_AspNetUsers_UserId" FOREIGN KEY ("UserId") REFERENCES "AspNetUsers" ("Id") ON DELETE CASCADE
);


CREATE TABLE "AspNetUserLogins" (
    "LoginProvider" text NOT NULL,
    "ProviderKey" text NOT NULL,
    "ProviderDisplayName" text,
    "UserId" text NOT NULL,
    CONSTRAINT "PK_AspNetUserLogins" PRIMARY KEY ("LoginProvider", "ProviderKey"),
    CONSTRAINT "FK_AspNetUserLogins_AspNetUsers_UserId" FOREIGN KEY ("UserId") REFERENCES "AspNetUsers" ("Id") ON DELETE CASCADE
);


CREATE TABLE "AspNetUserRoles" (
    "UserId" text NOT NULL,
    "RoleId" text NOT NULL,
    CONSTRAINT "PK_AspNetUserRoles" PRIMARY KEY ("UserId", "RoleId"),
    CONSTRAINT "FK_AspNetUserRoles_AspNetRoles_RoleId" FOREIGN KEY ("RoleId") REFERENCES "AspNetRoles" ("Id") ON DELETE CASCADE,
    CONSTRAINT "FK_AspNetUserRoles_AspNetUsers_UserId" FOREIGN KEY ("UserId") REFERENCES "AspNetUsers" ("Id") ON DELETE CASCADE
);


CREATE TABLE "AspNetUserTokens" (
    "UserId" text NOT NULL,
    "LoginProvider" text NOT NULL,
    "Name" text NOT NULL,
    "Value" text,
    CONSTRAINT "PK_AspNetUserTokens" PRIMARY KEY ("UserId", "LoginProvider", "Name"),
    CONSTRAINT "FK_AspNetUserTokens_AspNetUsers_UserId" FOREIGN KEY ("UserId") REFERENCES "AspNetUsers" ("Id") ON DELETE CASCADE
);


CREATE TABLE "WatchlistItems" (
    "Id" bigint GENERATED BY DEFAULT AS IDENTITY,
    "UserId" text NOT NULL,
    "Symbol" text NOT NULL,
    "CreatedAt" timestamp without time zone NOT NULL,
    CONSTRAINT "PK_WatchlistItems" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_WatchlistItems_AspNetUsers_UserId" FOREIGN KEY ("UserId") REFERENCES "AspNetUsers" ("Id") ON DELETE CASCADE
);


